interface Category {
  prices: number[];
  children: Category[];
}

function totalKobo(category: Category): number {
  const own = category.prices.reduce((sum, price) => sum + price, 0);
  return own + category.children.reduce((sum, child) => sum + totalKobo(child), 0);
}

